lessons.solution:
#include <stdio.h>

long fatorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * fatorial(n - 1);
}

int fibonacci(int n) {
    if (n < 2) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main(void) {
    int n;
    scanf("%d", &n);
    printf("Fatorial: %ld\n", fatorial(n));
    printf("Fibonacci: %d\n", fibonacci(n));
    return 0;
}

