#include <stdio.h>
#define MAX 100

void ordenar(int v[], int n) {
    int i, j, chave;
    for (i = 1; i < n; i++) {
        chave = v[i];
        j = i - 1;
        while (j >= 0 && v[j] > chave) {
            v[j + 1] = v[j];
            j--;
        }
        v[j + 1] = chave;
    }
}

int buscaBinaria(int v[], int n, int x) {
    int ini = 0;
    int fim = n - 1;
    int meio;
    while (ini <= fim) {
        meio = (ini + fim) / 2;
        if (v[meio] == x) {
            return meio;
        }
        if (v[meio] < x) {
            ini = meio + 1;
        } else {
            fim = meio - 1;
        }
    }
    return -1;
}

int main(void) {
    int v[MAX];
    int n, i, x, pos;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &v[i]);
    }
    scanf("%d", &x);
    ordenar(v, n);
    printf("Ordenado:");
    for (i = 0; i < n; i++) {
        printf(" %d", v[i]);
    }
    printf("\n");
    pos = buscaBinaria(v, n, x);
    if (pos >= 0) {
        printf("Posicao: %d\n", pos);
    } else {
        printf("Nao encontrado\n");
    }
    return 0;
}
